"source_fingerprint":"57720be6108078d09f52694bf0331f1cd041304008e975dac229ba4d257ad07f","cooking_tips":["四季豆須煮至內外全熟，粗豆要延長，不把保持爽脆當成可以生硬的理由。","瀝乾後才拌一湯匙現成醬，不另加生抽糖鹽，並核對所用醬汁的致敏原。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}]},"new":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"57720be6108078d09f52694bf0331f1cd041304008e975dac229ba4d257ad07f","cooking_tips":["四季豆須煮至內外全熟，粗豆要延長，不把保持爽脆當成可以生硬的理由。","瀝乾後才拌一湯匙現成醬，不另加生抽糖鹽，並核對所用醬汁的致敏原。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}],"served_cold":true}},{"id":"7c45d020-507b-4f8b-888b-167f2d8e68de","slug":"cucumber-shredded-chicken-soba","old":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"75964d77171f26ee81679de3cd6f2b75e0d095ee2078f23b5ee39ff0462bc3ae","cooking_tips":["熟麵沖涼須用飲用水或凍滾水，雞肉、菜及熟麵使用分開的乾淨器具。","雞肉先煮至75°C至少30秒再撕絲，拌好即食或及時冷藏，不把醋汁當成保鮮步驟。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"new":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"75964d77171f26ee81679de3cd6f2b75e0d095ee2078f23b5ee39ff0462bc3ae","cooking_tips":["熟麵沖涼須用飲用水或凍滾水，雞肉、菜及熟麵使用分開的乾淨器具。","雞肉先煮至75°C至少30秒再撕絲，拌好即食或及時冷藏，不把醋汁當成保鮮步驟。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true}}]$serving_patch$::jsonb);
DO $patch$
DECLARE rec record;
BEGIN
 IF (SELECT count(*) FROM serving_style_patch)<>4 THEN RAISE EXCEPTION 'Serving-style patch count changed'; END IF;
 PERFORM id FROM public.recipes WHERE id IN(SELECT(p->>'id')::uuid FROM serving_style_patch) ORDER BY id FOR UPDATE;
 FOR rec IN SELECT p FROM serving_style_patch LOOP
  IF NOT EXISTS(SELECT 1 FROM public.recipes WHERE id=(rec.p->>'id')::uuid AND is_public AND source_data->'editorial_guidance'=rec.p->'new') THEN
   RAISE EXCEPTION 'Serving-style precondition changed: %',rec.p->>'slug';
  END IF;
 END LOOP;
 FOR rec IN SELECT p FROM serving_style_patch LOOP
  UPDATE public.recipes SET source_data=jsonb_set(source_data,'{editorial_guidance}',rec.p->'old',true) WHERE id=(rec.p->>'id')::uuid;
 END LOOP;
END $patch$;
COMMIT;
